Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='staticsite', at=datetime(2026, 9, 30, 0, 0, 0), actor='assistant', title='suzatary web writes a static site of the attestable history, every page Typst behind the tripwire', body="*`suzatary web <outdir>`* (`suzatary_core::site`) is the chain's second consumer: a static site of the attestable history — every todo's lifecycle with each event's object hash and the objects it rests on, plus `objects/<hash>.py` a stranger can rehash. It reads only the objects and `view::entries` (so it is evidence about the stored format); nothing reads it back. Each page is Typst (`site::page::Page`, 2026-09-30), every string a literal through `escape_string` because every one came out of attacker-controlled mail, compiled whole by `render::Typst::document` behind the same `suspicious` tripwire; a refused page is replaced by one saying so. No stylesheet, no script. `suzatary todos open` is the open list the briefing reads, ascending in fulfillment, `(unconfirmed)` where the row stands.", rationale='The pages are Typst since 2026-09-30.', supersedes=()))